<?php require '../config/auth.php';login_required('student');$page_title='My Applications';$q=$pdo->prepare('SELECT a.*,j.job_title,c.company_name FROM applications a JOIN students s ON s.id=a.student_id JOIN jobs j ON j.id=a.job_id JOIN companies c ON c.id=j.company_id WHERE s.user_id=? ORDER BY a.applied_at DESC');$q->execute([$_SESSION['user_id']]);$rows=$q->fetchAll();require '../config/header.php';?><div class="head"><div><h1>My Applications</h1><p>Track every application and result.</p></div><a class="btn primary" href="jobs.php">Find Jobs</a></div><div class="card tablewrap"><table class="table"><tr><th>Company</th><th>Role</th><th>Applied</th><th>Status</th><th>Result</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['company_name'])?></td><td><?=e($r['job_title'])?></td><td><?=e(date('d M Y',strtotime($r['applied_at'])))?></td><td><span class="badge <?=in_array($r['status'],['selected'])?'green':(in_array($r['status'],['rejected'])?'red':'orange')?>"><?=e(ucwords(str_replace('_',' ',$r['status'])))?></span></td><td><?=in_array($r['status'],['selected','rejected'])?ucfirst($r['status']):'In progress'?></td></tr><?php endforeach;?></table><?php if(!$rows):?><div class="empty">No applications yet.</div><?php endif;?></div><?php require '../config/footer.php';?>
